const body = $json.body ?? $json;

const event = String(body.event ?? '')
  .trim()
  .toLowerCase();

const data = body.data ?? {};
const key = data.key ?? {};

const chat_id = String(key.remoteJid ?? '').trim();
const fromMe = key.fromMe === true;

const whatsapp_nombre = String(
  data.pushName ?? ''
).trim();

const message = data.message ?? {};

const texto = String(
  message.conversation ??
  message.extendedTextMessage?.text ??
  message.imageMessage?.caption ??
  message.videoMessage?.caption ??
  ''
).trim();

const match = texto.match(
  /^\/vincular\s+([A-Z0-9]{6})$/i
);

const codigo = match
  ? match[1].toUpperCase()
  : null;

const es_grupo =
  chat_id.endsWith('@g.us');

const es_vinculacion =
  event === 'messages.upsert' &&
  !fromMe &&
  !es_grupo &&
  !!chat_id &&
  !!codigo;

return [{
  json: {
    event,
    chat_id: chat_id || null,
    whatsapp_nombre: whatsapp_nombre || null,
    texto,
    codigo,
    fromMe,
    es_grupo,
    es_vinculacion
  }
}];

